/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: fixture, slot, mbid, manifestOf, tags, project, draftOf, track, synthetic, stored, intent,
 *              valuesOf, entry, completed, timed, code, copy
 *   Constants: guard, recorded, importId, actor, other, now
 * Tests
 *   - a release supplies its title, credit-ordered entries with join phrases, first label without an ID, group first-release date and each file's title, Disc and Track
 *   - recorded releases: a 9-track edition maps every file, a two-disc edition numbers its second disc, and a DVD without tracks is no disc
 *   - the entry after a featuring phrase and every later one is featured, ` x ` stays primary, and a repeated credit keeps only its first entry
 *   - placeholder-only credits supply no entries and are flagged, a [no label] label supplies nothing unflagged, and an empty credit list supplies nothing
 *   - control, invisible formatting, over-long, over-many and malformed values are left out and flagged, never stripped or truncated
 *   - the administrator's own values: equal case-insensitively is no conflict, a difference is an unanswered conflict that writes nothing, empty is filled, tag values are replaced
 *   - applying another candidate replaces only values still automatic; values the first wrote that the second lacks return to tag values or empty without an origin
 *   - choosing none returns lookup values to tag values, a previous answer to the same lookup value is kept, and the same candidate twice writes nothing
 *   - a track-count mismatch writes album values only, the 48 KB cap flags a value as size, and a path the stored draft lacks is skipped
 *   - an entry keeps the key of the current entry with its folded name and others derive a stable key, so decisions on unchanged entries are kept
 *   - a completed run applies its preselection once, never over this run's explicit choice, an unfetched candidate or a malformed draft
 *   - newly known durations re-rank stored candidates without a request and apply the new preselection; unchanged evidence re-ranks nothing
 *   - a re-rank binds the file set it ranked: a stale slot confirmed again is no longer stale, one still without a confirmed file stays stale
 *   - publication waits for a tie until a choice for that run, and for unanswered conflicts whose value still differs; an append ignores Album conflicts
 *   - choosing refuses another run, an active run, a candidate before completion or unknown as stale, and one without fetched details as incomplete
 *   - answering a conflict: lookup writes the value as the administrator's own, mine keeps it, and a stale application, path or base is refused
 *   - Artist entries and a label equal to the applied lookup values do not rest on file tags alone; differing ones still do
 *   - file-tag automation never replaces a value still resting on the applied lookup candidate, and fills the values lookup did not write
 *   - answering lookup for the Artist entries keeps decisions on reused entries only, and an answer that grows the draft past its cap is invalid
 *   - a conflict stored twice for one path is needed once
 * @end-catalog */

/**
 * Metadata lookup value application without a database: the values a fetched release supplies (recorded and synthetic
 * releases), the compare-and-set write path they share with tag automation, replacing and reverting applications, conflicts
 * with the administrator's own values and their answers, preselection, re-ranking, what publication waits for, and the
 * automatic markers. All names, identifiers and accounts are synthetic or come from recorded public fixtures.
 */
import assert from 'node:assert/strict';
import { readdirSync } from 'node:fs';
import path from 'node:path';
import { after, test } from 'node:test';
import { ObjectId } from 'mongodb';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import { AdminImportError, type ImportManifest } from '../../src/administration/import/adminImportContract';
import { defaultDraftV2, derivedEntryKey, type ImportArtistEntry, type ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import type { ImportAsset } from '../../src/administration/import/adminImportMediaTypes';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import { applyAutomaticValues, importAutomationMarkers } from '../../src/administration/import/adminImportValueState';
import { planImportAutomation } from '../../src/administration/import/adminImportAutomation';
import { METADATA_LOOKUP_JOB_LIMITS, type MusicBrainzRelease } from '../../src/administration/lookup/lookupContract';
import {
    applyLookupCandidate, applyPreselectedLookup, chooseLookupCandidate, lookupAnswersNeeded, lookupCandidateValues, rerankStoredLookup, resolveLookupConflicts,
    sameLookupValue, type LookupApplicationIntent
} from '../../src/administration/lookup/lookupValueApplication';
import {
    lookupFileEvidence, rankLookupWithinBudget, type LookupApplication, type MetadataLookupRecord, type StoredLookupCandidate
} from '../../src/administration/lookup/metadataLookupRecord';
import { parseMusicBrainzRelease } from '../../src/administration/lookup/musicBrainzClient';
import { fixtureRoot, loadLookupFixture } from '../support/metadataLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const recorded = new Map<string, MusicBrainzRelease>(readdirSync(path.join(fixtureRoot, 'musicbrainz'))
    .filter(name => /^release-[0-9a-f-]{36}\.json$/.test(name))
    .map(name => parseMusicBrainzRelease(loadLookupFixture(`musicbrainz/${name}`).exchanges.at(-1)!.body))
    .map(release => [release.releaseId, release]));
const fixture = (prefix: string) => [...recorded.values()].find(release => release.releaseId.startsWith(prefix))!;

const importId = '0000000000000000000000d1', actor = '0000000000000000000000e1', other = '0000000000000000000000e2';
const now = new Date('2026-10-19T00:00:00Z');
const slot = (index: number) => `0000000a-0000-4000-a000-${String(index + 1).padStart(12, '0')}`;
const mbid = (index: number) => `0000000b-0000-4000-8000-${String(index).padStart(12, '0')}`;
const manifestOf = (count: number): ImportManifest => ({ rootLabel: 'Synthetic Folder',
    files: Array.from({ length: count }, (_unused, index) => ({ slotId: slot(index), filename: `${index}.flac`, relativePath: `Synthetic Folder/${index}.flac`, byteLength: 1 })) });
const tags = (extra: Record<string, unknown> = {}) => ({ version: 2, title: null, album: null, artists: [], albumArtists: [], label: null, year: null, discNumber: null, trackNumber: null,
    durationMs: null, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, flagged: [], ...extra });
/** An import of `count` confirmed files, each with the given version-2 evidence, and an empty Draft v2. */
function project(count: number, evidence: (index: number) => Record<string, unknown> | null = () => tags(), extra: Partial<AdminImportDocument> = {}): AdminImportDocument {
    const manifest = manifestOf(count);
    const assets = manifest.files.map((file, index) => ({ slotId: file.slotId, operationId: mbid(500 + index), state: 'ready', sha256: 'a'.repeat(64), duration: null,
        tags: evidence(index) }) as unknown as ImportAsset);
    return { _id: new ObjectId(importId), purpose: 'import', draftVersion: 2, draft: defaultDraftV2(manifest), draftOrigins: {}, manifest, media: { assets },
        revision: 3, valueRevision: 0, decisions: [], suggestions: [], receipts: [], updatedAt: new Date(0), ...extra } as unknown as AdminImportDocument;
}
const draftOf = (doc: AdminImportDocument) => doc.draft as ImportDraftV2;
const track = (position: number, title: string, lengthMs: number | null = 200_000 + position * 10_000) =>
    ({ position, number: String(position), title, lengthMs, recordingId: mbid(900 + position), isrcs: [] });
/** A synthetic two-track release: two credits joined by ` & `, two labels, a group first-release date and a later release date. */
const synthetic = (id: number, extra: Partial<MusicBrainzRelease> = {}): MusicBrainzRelease => ({
    releaseId: mbid(id), releaseGroupId: mbid(100 + id), title: 'Synthetic Album', status: 'Official',
    artistCredit: [{ name: 'Synthetic Lead', joinPhrase: ' & ', artistId: mbid(1), artistName: 'Synthetic Lead' },
        { name: 'Synthetic Second', joinPhrase: '', artistId: mbid(2), artistName: 'Synthetic Second' }],
    labels: [{ name: 'Synthetic Label', labelId: mbid(10), catalogNumber: 'SYN-001' }, { name: 'Second Label', labelId: mbid(11), catalogNumber: null }],
    barcode: null, barcodeText: null, country: 'JP', date: { year: 2021, month: 5, day: 1 }, primaryType: 'Album', secondaryTypes: [], trackCount: 2,
    groupFirstReleaseDate: { year: 2020, month: 3, day: null },
    media: [{ position: 1, format: 'CD', tracks: [track(1, 'First Song'), track(2, 'Second Song')] }], frontArtwork: null, ...extra
});
const stored = (release: MusicBrainzRelease, details: StoredLookupCandidate['details'] = 'fetched'): StoredLookupCandidate =>
    ({ key: `musicbrainz:${release.releaseId}`, source: 'musicbrainz', releaseId: release.releaseId, basis: 'albumText', summary: null, release: details === 'fetched' ? release : null, details });
const intent = (extra: Partial<LookupApplicationIntent> = {}): LookupApplicationIntent => ({ run: 1, choice: 'chosen', basis: 'chosen', actorId: actor, operationId: mbid(700), now, ...extra });
const valuesOf = (doc: AdminImportDocument, release: MusicBrainzRelease) => lookupCandidateValues(release, lookupFileEvidence(doc), draftOf(doc), importId);
const entry = (name: string, role: ImportArtistEntry['role'] = 'primary', joinPhrase: string | null = null): ImportArtistEntry =>
    ({ key: derivedEntryKey({ importId, lookupEntry: name.normalize('NFC').toLowerCase() }), name, role, joinPhrase, musicBrainzId: null });
/** A completed run ranked against the import's current files, with `applied` as given. */
function completed(doc: AdminImportDocument, candidates: StoredLookupCandidate[], extra: Partial<MetadataLookupRecord> = {}): MetadataLookupRecord {
    const ranked = rankLookupWithinBudget(candidates, doc, now);
    return { _id: doc._id, run: 1, state: 'complete', issue: null, outcome: 'candidates', operationId: mbid(600), actorId: actor, grantSource: 'upload',
        grantExpiresAt: new Date(now.getTime() + 60_000), automatic: true, input: { trigger: 'tags', submitted: null }, queries: [], queryIndex: 0, phase: 'done',
        fileSetDigest: 'digest', files: [], attempts: { musicbrainz: 0 }, retryAt: null, candidates: ranked.candidates, ranking: ranked.ranking, applied: null,
        staleSlotIds: [], automaticRuns: 1, folderUsed: false, leaseOwner: null, leaseUntil: null, createdAt: now, updatedAt: now, completedAt: now, ...extra };
}
/** Files whose durations match the synthetic releases' two tracks. */
const timed = (index: number) => tags({ durationMs: 200_000 + (index + 1) * 10_000 });
const code = (expected: string) => (error: unknown) => error instanceof AdminImportError && error.code === expected;
/** A deep copy that keeps the ObjectId (structuredClone drops its prototype). */
const copy = (doc: AdminImportDocument): AdminImportDocument => ({ ...structuredClone(doc), _id: doc._id });

test('a release supplies its title, credit-ordered entries with join phrases, first label without an ID, group first-release date and each file\'s title, Disc and Track', () => {
    const doc = project(2);
    assert.deepEqual(valuesOf(doc, synthetic(1)), { flagged: [], values: [
        { path: 'album.title', value: 'Synthetic Album', slotId: null },
        { path: 'album.artists', value: [entry('Synthetic Lead', 'primary', ' & '), entry('Synthetic Second')], slotId: null },
        { path: 'album.label', value: { name: 'Synthetic Label', musicBrainzId: null }, slotId: null },
        { path: 'album.releaseDate', value: { year: 2020, month: 3, day: null }, slotId: null },
        { path: `tracks.${slot(0)}.title`, value: 'First Song', slotId: slot(0) }, { path: `tracks.${slot(0)}.discNumber`, value: 1, slotId: slot(0) },
        { path: `tracks.${slot(0)}.trackNumber`, value: 1, slotId: slot(0) },
        { path: `tracks.${slot(1)}.title`, value: 'Second Song', slotId: slot(1) }, { path: `tracks.${slot(1)}.discNumber`, value: 1, slotId: slot(1) },
        { path: `tracks.${slot(1)}.trackNumber`, value: 2, slotId: slot(1) }] });
    // The group's first-release date keeps its precision; without one the release's own date is used.
    const date = (release: MusicBrainzRelease) => valuesOf(doc, release).values.find(value => value.path === 'album.releaseDate')?.value ?? null;
    assert.deepEqual(date(synthetic(1, { groupFirstReleaseDate: { year: 2019, month: null, day: null } })), { year: 2019, month: null, day: null });
    assert.deepEqual(date(synthetic(1, { groupFirstReleaseDate: { year: 2019, month: 2, day: 28 } })), { year: 2019, month: 2, day: 28 });
    assert.deepEqual(date(synthetic(1, { groupFirstReleaseDate: null })), { year: 2021, month: 5, day: 1 });
    assert.equal(date(synthetic(1, { groupFirstReleaseDate: null, date: null })), null);
    // Files take tracks in the ranking's order: by the draft's Track Numbers when known.
    draftOf(doc).tracks[0].trackNumber = 2; draftOf(doc).tracks[1].trackNumber = 1;
    const titles = valuesOf(doc, synthetic(1)).values.filter(value => value.path.endsWith('.title') && value.slotId).map(value => [value.slotId, value.value]);
    assert.deepEqual(titles, [[slot(1), 'First Song'], [slot(0), 'Second Song']]);
});

test('recorded releases: a 9-track edition maps every file, a two-disc edition numbers its second disc, and a DVD without tracks is no disc', () => {
    const hotel = fixture('24ae881f'), nine = project(9);
    const values = valuesOf(nine, hotel).values;
    assert.equal(values.filter(value => value.path.endsWith('.trackNumber')).length, 9);
    assert.deepEqual(values.find(value => value.path === `tracks.${slot(8)}.title`)!.value, hotel.media[0].tracks[8].title);
    assert.ok(values.some(value => value.path === 'album.title' && value.value === 'Hotel California'));
    const cd = fixture('8baecda4'), two = project(39), cdValues = valuesOf(two, cd).values;
    assert.deepEqual(cdValues.filter(value => value.slotId === slot(20)).map(value => value.value), [cd.media[1].tracks[0].title, 2, 1]);
    assert.deepEqual(cdValues.find(value => value.path === 'album.artists')!.value, [entry('Mitsukiyo', 'primary', '、'), entry('KARUT', 'primary', '、'), entry('Nor')]);
    assert.deepEqual(cdValues.find(value => value.path === 'album.releaseDate')!.value, { year: 2022, month: 3, day: 24 });
    const dvd = synthetic(1, { media: [{ position: 1, format: 'DVD', tracks: [] }, { position: 2, format: 'CD', tracks: [track(1, 'First Song'), track(2, 'Second Song')] }] });
    assert.deepEqual(valuesOf(project(2), dvd).values.filter(value => value.path.endsWith('.discNumber')).map(value => value.value), [1, 1]);
});

test('the entry after a featuring phrase and every later one is featured, ` x ` stays primary, and a repeated credit keeps only its first entry', () => {
    const credits = (phrase: string) => synthetic(1, { artistCredit: [{ name: 'Lead', joinPhrase: phrase, artistId: mbid(1), artistName: 'Lead' },
        { name: 'Guest', joinPhrase: ' & ', artistId: mbid(2), artistName: 'Guest' }, { name: 'Third', joinPhrase: '', artistId: mbid(3), artistName: 'Third' }] });
    const roles = (release: MusicBrainzRelease) => (valuesOf(project(2), release).values.find(value => value.path === 'album.artists')!.value as ImportArtistEntry[]).map(item => item.role);
    for (const phrase of [' feat. ', ' featuring ', ' (ft. ']) assert.deepEqual(roles(credits(phrase)), ['primary', 'featured', 'featured'], phrase);
    assert.deepEqual(roles(credits(' x ')), ['primary', 'primary', 'primary']);
    const repeated = synthetic(1, { artistCredit: [{ name: 'Lead', joinPhrase: ' & ', artistId: mbid(1), artistName: 'Lead' },
        { name: 'Lead Alias', joinPhrase: ' & ', artistId: mbid(1), artistName: 'Lead' }, { name: 'LEAD', joinPhrase: ' & ', artistId: mbid(4), artistName: 'Other' },
        { name: 'Guest', joinPhrase: '', artistId: mbid(2), artistName: 'Guest' }] });
    assert.deepEqual(valuesOf(project(2), repeated).values.find(value => value.path === 'album.artists')!.value, [entry('Lead', 'primary', ' & '), entry('Guest')]);
});

test('placeholder-only credits supply no entries and are flagged, a [no label] label supplies nothing unflagged, and an empty credit list supplies nothing', () => {
    const various = synthetic(1, { artistCredit: [{ name: 'Various Artists', joinPhrase: '', artistId: '89ad4ac3-39f7-470e-963a-56509c546377', artistName: 'Various Artists' }],
        labels: [{ name: '[no label]', labelId: '157afde4-4bf5-4039-8ad2-5a15acc85176', catalogNumber: null }, { name: 'Second Label', labelId: mbid(11), catalogNumber: null }] });
    const result = valuesOf(project(2), various);
    assert.deepEqual(result.flagged, [{ path: 'album.artists', reason: 'placeholder' }]);
    assert.equal(result.values.some(value => value.path === 'album.artists' || value.path === 'album.label'), false);
    const nothing = valuesOf(project(2), synthetic(1, { artistCredit: [], labels: [] }));
    assert.deepEqual([nothing.flagged, nothing.values.map(value => value.path).filter(path => path.startsWith('album.'))], [[], ['album.title', 'album.releaseDate']]);
    // A placeholder beside a real credit is dropped silently.
    const mixed = synthetic(1, { artistCredit: [{ name: '[unknown]', joinPhrase: ' & ', artistId: '125ec42a-7229-4250-afc5-e057484327fe', artistName: '[unknown]' },
        { name: 'Real Artist', joinPhrase: '', artistId: mbid(2), artistName: 'Real Artist' }] });
    assert.deepEqual(valuesOf(project(2), mixed).values.find(value => value.path === 'album.artists')!.value, [entry('Real Artist')]);
});

test('control, invisible formatting, over-long, over-many and malformed values are left out and flagged, never stripped or truncated', () => {
    const flags = (release: MusicBrainzRelease) => valuesOf(project(2), release);
    const zeroWidth = flags(synthetic(1, { title: 'Zero\u200bWidth' }));
    assert.deepEqual([zeroWidth.flagged, zeroWidth.values.some(value => value.path === 'album.title')], [[{ path: 'album.title', reason: 'characters' }], false]);
    const credit = (name: string, joinPhrase = '') => ({ name, joinPhrase, artistId: mbid(30), artistName: name });
    for (const [label, credits, reason] of [
        ['a control character', [credit('Bell\u0007')], 'characters'],
        ['a lone surrogate', [credit('Half\ud800')], 'characters'],
        ['an over-long name', [credit('n'.repeat(201))], 'length'],
        ['21 entries', Array.from({ length: 21 }, (_unused, index) => ({ ...credit(`Artist ${index}`, index < 20 ? ', ' : ''), artistId: mbid(40 + index) })), 'length'],
        ['an invisible join phrase', [credit('Lead', ' \u200b '), { ...credit('Guest'), artistId: mbid(31) }], 'format'],
        ['an over-long join phrase', [credit('Lead', ' and together with '), { ...credit('Guest'), artistId: mbid(31) }], 'format']
    ] as const) {
        const result = flags(synthetic(1, { artistCredit: [...credits] }));
        assert.deepEqual(result.flagged, [{ path: 'album.artists', reason }], label);
        assert.equal(result.values.some(value => value.path === 'album.artists'), false, label);
    }
    const label = flags(synthetic(1, { labels: [{ name: 'l'.repeat(201), labelId: mbid(10), catalogNumber: null }] }));
    assert.deepEqual(label.flagged, [{ path: 'album.label', reason: 'length' }]);
    const longTrack = flags(synthetic(1, { media: [{ position: 1, format: 'CD', tracks: [track(1, 't'.repeat(301)), track(2, 'Second\u200d')] }] }));
    assert.deepEqual(longTrack.flagged, [{ path: `tracks.${slot(0)}.title`, reason: 'length' }, { path: `tracks.${slot(1)}.title`, reason: 'characters' }]);
    assert.deepEqual(longTrack.values.filter(value => value.slotId).map(value => value.path), [`tracks.${slot(0)}.discNumber`, `tracks.${slot(0)}.trackNumber`,
        `tracks.${slot(1)}.discNumber`, `tracks.${slot(1)}.trackNumber`]);
    // Text is NFC and trimmed; a whitespace-only title is no value.
    assert.equal(flags(synthetic(1, { title: '  Cafe\u0301 ' })).values[0].value, 'Caf\u00e9');
    assert.equal(flags(synthetic(1, { title: '   ' })).values.some(value => value.path === 'album.title'), false);
});

test('the administrator\'s own values: equal case-insensitively is no conflict, a difference is an unanswered conflict that writes nothing, empty is filled, tag values are replaced', () => {
    const doc = project(2), draft = draftOf(doc);
    draft.album.title = 'Synthetic Album'; draft.album.artists = [{ ...entry('synthetic lead', 'primary', ' & '), key: mbid(800) }, { ...entry('Synthetic Second'), key: mbid(801) }];
    draft.album.label = { name: 'Mine', musicBrainzId: null }; draft.tracks[0].title = 'Tagged First';
    doc.draftOrigins = { 'album:title': 'administrator', 'album:artists': 'administrator', 'album:label': 'administrator', 'album:releaseDate': 'administrator',
        [`tracks:${slot(0)}:title`]: 'automatic' };
    const before = structuredClone(doc), { application, changed } = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    assert.equal(changed, true);
    assert.deepEqual(application.conflicts, [{ path: 'album.label', lookup: { name: 'Synthetic Label', musicBrainzId: null }, slotId: null, answer: null }]);
    assert.deepEqual([draft.album.title, draft.album.artists, draft.album.label], [before.draft.album.title, (before.draft as ImportDraftV2).album.artists, { name: 'Mine', musicBrainzId: null }]);
    assert.deepEqual([draft.album.releaseDate, doc.draftOrigins['album:releaseDate'], draft.tracks[0].title, doc.draftOrigins[`tracks:${slot(0)}:title`]],
        [{ year: 2020, month: 3, day: null }, 'automatic', 'First Song', 'automatic']);
    // Only automatic values equal to the candidate rest on it; the administrator's equal values stay theirs.
    assert.equal(application.values.some(value => ['album.title', 'album.artists', 'album.label'].includes(value.path)), false);
    assert.ok(application.values.some(value => value.path === 'album.releaseDate'));
    assert.deepEqual([doc.valueRevision, doc.revision, doc.receipts, doc.updatedAt], [1, 3, [], now]);
    assert.deepEqual(application.paths.sort(), ['album.releaseDate', ...[0, 1].flatMap(index => ['title', 'discNumber', 'trackNumber'].map(field => `tracks.${slot(index)}.${field}`))].sort());
    // A label that differs only by case is the same label; another role or join phrase is a difference.
    assert.equal(sameLookupValue('album.label', { name: 'synthetic label', musicBrainzId: mbid(9) }, { name: 'Synthetic Label', musicBrainzId: null }), true);
    assert.equal(sameLookupValue('album.artists', [entry('Lead', 'featured')], [entry('lead')]), false);
    assert.equal(sameLookupValue('album.artists', [entry('Lead', 'primary', ' & ')], [entry('lead')]), false);
    assert.equal(sameLookupValue('album.label', null, null), true);
    assert.equal(sameLookupValue('album.label', null, { name: 'X', musicBrainzId: null }), false);
});

test('applying another candidate replaces only values still automatic; values the first wrote that the second lacks return to tag values or empty without an origin', () => {
    const doc = project(2, index => tags({ title: `Tagged ${index}`, album: 'Tagged Album', label: 'Tagged Label', albumArtists: ['Tagged Ensemble'] }));
    applyAutomaticValues({ draft: draftOf(doc), draftOrigins: doc.draftOrigins! }, planImportAutomation(doc).values);
    const tagged = structuredClone(draftOf(doc));
    const first = applyLookupCandidate(doc, null, stored(synthetic(1)), intent({ choice: 'preselected', basis: 'onlyMatchingGroup', operationId: null }));
    assert.deepEqual([draftOf(doc).album.title, draftOf(doc).album.label, draftOf(doc).tracks.map(item => [item.title, item.discNumber, item.trackNumber])],
        ['Synthetic Album', { name: 'Synthetic Label', musicBrainzId: null }, [['First Song', 1, 1], ['Second Song', 1, 2]]]);
    // The administrator then edits the second track's title.
    draftOf(doc).tracks[1].title = 'Typed Second'; doc.draftOrigins![`tracks:${slot(1)}:title`] = 'administrator';
    const second = synthetic(2, { title: 'Other Album', labels: [], groupFirstReleaseDate: null, date: null,
        media: [{ position: 1, format: 'CD', tracks: [track(1, 'A'), track(2, 'B'), track(3, 'C')] }] });
    const replaced = applyLookupCandidate(doc, first.application, stored(second), intent({ run: 2 }));
    const draft = draftOf(doc);
    assert.deepEqual([draft.album.title, draft.album.artists, draft.album.label, draft.album.releaseDate], ['Other Album', first.application.values[1].value, tagged.album.label, null]);
    assert.deepEqual(draft.tracks.map(item => [item.title, item.discNumber, item.trackNumber]), [['Tagged 0', null, null], ['Typed Second', null, null]]);
    // Emptied values have no origin; reverted tag values and the second candidate's values are automatic; the edit stays the administrator's.
    assert.deepEqual(Object.fromEntries(Object.entries(doc.draftOrigins!).sort()), Object.fromEntries(Object.entries({
        'album:artists': 'automatic', 'album:label': 'automatic', 'album:title': 'automatic', [`tracks:${slot(0)}:title`]: 'automatic', [`tracks:${slot(1)}:title`]: 'administrator'
    }).sort()));
    assert.deepEqual(replaced.application.values.map(value => value.path), ['album.title', 'album.artists']);
    assert.deepEqual([replaced.application.candidateKey, replaced.application.choice, replaced.changed, doc.valueRevision], [`musicbrainz:${mbid(2)}`, 'chosen', true, 2]);
});

test('choosing none returns lookup values to tag values, a previous answer to the same lookup value is kept, and the same candidate twice writes nothing', () => {
    const doc = project(2, index => tags({ title: `Tagged ${index}` }));
    applyAutomaticValues({ draft: draftOf(doc), draftOrigins: doc.draftOrigins! }, planImportAutomation(doc).values);
    draftOf(doc).album.label = { name: 'Mine', musicBrainzId: null }; doc.draftOrigins!['album:label'] = 'administrator';
    const first = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    const answered: LookupApplication = { ...first.application, conflicts: first.application.conflicts.map(item => ({ ...item, answer: 'mine' as const })) };
    const snapshot = structuredClone(doc), again = applyLookupCandidate(doc, answered, stored(synthetic(1)), intent({ run: 2 }));
    assert.deepEqual([again.changed, doc.valueRevision, doc.draft, again.application.conflicts], [false, snapshot.valueRevision, snapshot.draft,
        [{ path: 'album.label', lookup: { name: 'Synthetic Label', musicBrainzId: null }, slotId: null, answer: 'mine' }]]);
    // Another lookup value for the same path is a new question.
    const relabelled = applyLookupCandidate(copy(doc), answered, stored(synthetic(3, { labels: [{ name: 'Third Label', labelId: null, catalogNumber: null }] })), intent());
    assert.equal(relabelled.application.conflicts[0].answer, null);
    const none = applyLookupCandidate(doc, again.application, null, intent({ run: 2, choice: 'none', basis: null }));
    assert.deepEqual(draftOf(doc).tracks.map(item => [item.title, item.trackNumber]), [['Tagged 0', null], ['Tagged 1', null]]);
    assert.deepEqual([draftOf(doc).album.title, draftOf(doc).album.label, none.application.values, none.application.conflicts, none.application.candidateKey],
        ['', { name: 'Mine', musicBrainzId: null }, [], [], null]);
    assert.equal(doc.draftOrigins!['album:title'], undefined);
});

test('a track-count mismatch writes album values only, the 48 KB cap flags a value as size, and a path the stored draft lacks is skipped', () => {
    const three = synthetic(1, { media: [{ position: 1, format: 'CD', tracks: [track(1, 'A'), track(2, 'B'), track(3, 'C')] }] });
    const doc = project(2), mismatch = applyLookupCandidate(doc, null, stored(three), intent());
    assert.deepEqual(mismatch.application.paths, ['album.title', 'album.artists', 'album.label', 'album.releaseDate']);
    const full = project(2), draft = draftOf(full);
    draft.album.title = 'x'.repeat(47_995 - JSON.stringify({ ...draft, album: { ...draft.album, title: '' } }).length); full.draftOrigins!['album:title'] = 'administrator';
    const capped = applyLookupCandidate(full, null, stored(synthetic(1)), intent());
    assert.ok(capped.application.flagged.some(flag => flag.path === `tracks.${slot(0)}.title` && flag.reason === 'size'));
    assert.equal(draft.tracks[0].title, '');
    assert.ok(JSON.stringify(full.draft).length <= 48_000);
    // A malformed stored draft that lost a track: that file's values and a recorded value on its path are skipped, the rest written.
    const lost = project(2); draftOf(lost).tracks.splice(1, 1);
    const previous: LookupApplication = { ...mismatch.application, values: [{ path: `tracks.${slot(1)}.title`, value: 'Gone', slotId: slot(1) }] };
    lost.draftOrigins![`tracks:${slot(1)}:title`] = 'automatic';
    const partial = applyLookupCandidate(lost, previous, stored(synthetic(1)), intent());
    assert.equal(partial.application.paths.some(item => item.includes(slot(1))), false);
    assert.ok(partial.application.paths.includes(`tracks.${slot(0)}.title`));
});

test('an entry keeps the key of the current entry with its folded name and others derive a stable key, so decisions on unchanged entries are kept', () => {
    const doc = project(2), kept = mbid(810);
    draftOf(doc).album.artists = [{ key: kept, name: 'Synthetic Lead', role: 'primary', joinPhrase: null, musicBrainzId: null }, { key: mbid(811), name: 'Gone', role: 'primary', joinPhrase: null, musicBrainzId: null }];
    doc.draftOrigins!['album:artists'] = 'automatic';
    const decision = (entryKey: string, boundName: string) => ({ scope: 'artist', slotId: null, entryKey, boundName, action: 'create-distinct', candidateId: null, candidateRevision: null });
    doc.decisions = [decision(kept, 'Synthetic Lead'), decision(mbid(811), 'Gone'), { ...decision(kept, 'x'), scope: 'album', entryKey: null, boundName: null }] as AdminImportDocument['decisions'];
    applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    assert.deepEqual(draftOf(doc).album.artists.map(item => item.key), [kept, derivedEntryKey({ importId, lookupEntry: 'synthetic second' })]);
    assert.deepEqual(doc.decisions.map(item => (item as { entryKey: string | null }).entryKey), [kept, null]);
    // The same entries on another import of the same ID derive the same keys.
    const fresh = project(2);
    applyLookupCandidate(fresh, null, stored(synthetic(1)), intent());
    assert.deepEqual(draftOf(fresh).album.artists, [entry('Synthetic Lead', 'primary', ' & '), entry('Synthetic Second')]);
});

test('a completed run applies its preselection once, never over this run\'s explicit choice, an unfetched candidate or a malformed draft', () => {
    const doc = project(2, timed), run = completed(doc, [stored(synthetic(1))]);
    assert.equal(run.ranking!.preselection?.basis, 'onlyMatchingGroup');
    const first = applyPreselectedLookup(doc, run, now);
    assert.deepEqual([first.changed, first.record.applied?.choice, first.record.applied?.basis, first.record.applied?.actorId, first.record.applied?.operationId, doc.valueRevision],
        [true, 'preselected', 'onlyMatchingGroup', actor, null, 1]);
    const again = applyPreselectedLookup(doc, first.record, now);
    assert.deepEqual([again.changed, again.record], [false, first.record]);
    const explicit = { ...run, applied: { ...first.record.applied!, choice: 'none' as const, candidateKey: null } };
    assert.equal(applyPreselectedLookup(project(2, timed), explicit, now).record, explicit);
    const unfetched = completed(doc, [stored(synthetic(1))]);
    unfetched.candidates = unfetched.candidates.map(candidate => ({ ...candidate, details: 'failed', release: null }));
    assert.equal(applyPreselectedLookup(project(2, timed), unfetched, now).changed, false);
    const malformed = project(2, timed, { draft: { album: null } as never });
    assert.deepEqual(applyPreselectedLookup(malformed, run, now), { record: run, changed: false });
    // An earlier run's application is replaced by this run's preselection.
    const earlier = applyPreselectedLookup(project(2, timed), { ...run, run: 2, applied: first.record.applied }, now);
    assert.equal(earlier.record.applied?.run, 2);
});

test('newly known durations re-rank stored candidates without a request and apply the new preselection; unchanged evidence re-ranks nothing', () => {
    const doc = project(2), run = completed(doc, [stored(synthetic(1)), stored(synthetic(2, { media: [{ position: 1, format: 'CD', tracks: [track(1, 'X', 100_000), track(2, 'Y', 100_000)] }] }))]);
    assert.equal(run.ranking!.preselection, null);
    assert.equal(rerankStoredLookup(doc, run, now), null);
    doc.media!.assets.forEach((asset, index) => { asset.tags = timed(index) as never; });
    const evidence = lookupFileEvidence(doc), reranked = rerankStoredLookup(doc, run, now, other)!;
    assert.deepEqual([reranked.changed, reranked.record.ranking!.preselection?.candidateKey, reranked.record.applied?.candidateKey, reranked.record.applied?.actorId,
        reranked.record.actorId, draftOf(doc).album.title], [true, `musicbrainz:${mbid(1)}`, `musicbrainz:${mbid(1)}`, other, actor, 'Synthetic Album']);
    assert.deepEqual(reranked.record.ranking!.files, evidence);
    // The Disc and Track Numbers the application wrote are no new evidence (they follow the ranking's file order).
    assert.notDeepEqual(lookupFileEvidence(doc), evidence);
    assert.equal(rerankStoredLookup(doc, reranked.record, now), null);
    for (const state of ['queued', 'stopped'] as const) assert.equal(rerankStoredLookup(doc, { ...run, state }, now), null, state);
    assert.equal(rerankStoredLookup(doc, { ...run, outcome: 'noRelease' }, now), null);
    assert.deepEqual(guard.attempts, []);
});

test('a re-rank binds the file set it ranked: a stale slot confirmed again is no longer stale, one still without a confirmed file stays stale', () => {
    const doc = project(3), bound = [0, 1, 2].map(index => ({ slotId: slot(index), operationId: mbid(400 + index), sha256: 'b'.repeat(64) }));
    const run = completed(doc, [stored(synthetic(1))], { files: bound, staleSlotIds: [slot(0), slot(2)] });
    // Slot 0's file was replaced and confirmed, slot 2's removed; durations are newly known.
    doc.media!.assets = doc.media!.assets.filter(asset => asset.slotId !== slot(2));
    doc.media!.assets.forEach((asset, index) => { asset.tags = timed(index) as never; });
    const reranked = rerankStoredLookup(doc, run, now)!;
    assert.deepEqual([reranked.record.staleSlotIds, reranked.record.files, reranked.record.fileSetDigest],
        [[slot(2)], [{ slotId: slot(0), operationId: mbid(500), sha256: 'a'.repeat(64) }, { slotId: slot(1), operationId: mbid(501), sha256: 'a'.repeat(64) },
            { slotId: slot(2), operationId: null, sha256: null }], run.fileSetDigest]);
});

test('publication waits for a tie until a choice for that run, and for unanswered conflicts whose value still differs; an append ignores Album conflicts', () => {
    const doc = project(2, timed), labelled = (id: number, name: string) => synthetic(id, { labels: [{ name, labelId: null, catalogNumber: null }] });
    const tie = completed(doc, [stored(labelled(1, 'First Label')), stored(labelled(2, 'Second Label'))]);
    assert.deepEqual([tie.ranking!.groups.length, tie.ranking!.preselection], [2, null]);
    assert.deepEqual(lookupAnswersNeeded(tie, doc, { append: false }), { tie: true, conflicts: [] });
    assert.deepEqual(lookupAnswersNeeded(tie, doc, { append: true }), { tie: true, conflicts: [] });
    const chosen = chooseLookupCandidate(doc, tie, { run: 1, candidateKey: `musicbrainz:${mbid(2)}`, actorId: other, operationId: mbid(701) }, now);
    assert.equal(lookupAnswersNeeded(chosen, doc, { append: false }).tie, false);
    assert.equal(lookupAnswersNeeded({ ...chosen, run: 2 }, doc, { append: false }).tie, true, 'a choice for an earlier run answers nothing now');
    const none = chooseLookupCandidate(project(2, timed), tie, { run: 1, candidateKey: null, actorId: other, operationId: mbid(702) }, now);
    assert.equal(lookupAnswersNeeded(none, doc, { append: false }).tie, false);
    assert.equal(lookupAnswersNeeded({ ...tie, state: 'stopped' }, doc, { append: false }).tie, false);

    const mine = project(2, timed);
    draftOf(mine).album.label = { name: 'Mine', musicBrainzId: null }; draftOf(mine).tracks[0].title = 'Mine'; mine.draftOrigins = { 'album:label': 'administrator', [`tracks:${slot(0)}:title`]: 'administrator' };
    const conflicted = applyPreselectedLookup(mine, completed(mine, [stored(synthetic(1))]), now).record;
    assert.deepEqual(lookupAnswersNeeded(conflicted, mine, { append: false }), { tie: false, conflicts: ['album.label', `tracks.${slot(0)}.title`] });
    assert.deepEqual(lookupAnswersNeeded(conflicted, mine, { append: true }).conflicts, [`tracks.${slot(0)}.title`]);
    // An answer, or a current value made equal (case-insensitively for a label), needs nothing more.
    const answered = { ...conflicted, applied: { ...conflicted.applied!, conflicts: conflicted.applied!.conflicts.map(item => ({ ...item, answer: 'mine' as const })) } };
    assert.deepEqual(lookupAnswersNeeded(answered, mine, { append: false }).conflicts, []);
    draftOf(mine).album.label = { name: 'SYNTHETIC LABEL', musicBrainzId: null };
    assert.deepEqual(lookupAnswersNeeded(conflicted, mine, { append: false }).conflicts, [`tracks.${slot(0)}.title`]);
    // Malformed stored items and records never block.
    const malformed = { ...conflicted, applied: { ...conflicted.applied!, conflicts: [null, { path: 'album.visibility', lookup: 'public', answer: null }, { path: 'album.title', lookup: 'x' },
        { path: '__proto__', lookup: 1, answer: null }] as never } };
    assert.deepEqual(lookupAnswersNeeded(malformed, mine, { append: false }), { tie: false, conflicts: [] });
    assert.deepEqual(lookupAnswersNeeded(null, mine, { append: false }), { tie: false, conflicts: [] });
    assert.deepEqual(lookupAnswersNeeded({ ...conflicted, ranking: 'x' as never, applied: 'y' as never }, mine, { append: false }), { tie: false, conflicts: [] });
});

test('choosing refuses another run, an active run, a candidate before completion or unknown as stale, and one without fetched details as incomplete', () => {
    const doc = project(2, timed), run = completed(doc, [stored(synthetic(1)), stored(synthetic(2), 'failed')]);
    const choose = (record: MetadataLookupRecord | null, candidateKey: string | null, runNumber = 1) =>
        () => chooseLookupCandidate(project(2, timed), record, { run: runNumber, candidateKey, actorId: other, operationId: mbid(703) }, now);
    assert.throws(choose(null, null), code('ADMIN_IMPORT_LOOKUP_STALE'));
    assert.throws(choose(run, null, 2), code('ADMIN_IMPORT_LOOKUP_STALE'));
    for (const state of ['queued', 'running', 'retrying'] as const) assert.throws(choose({ ...run, state }, null), code('ADMIN_IMPORT_LOOKUP_STALE'), state);
    assert.throws(choose({ ...run, state: 'unavailable' }, `musicbrainz:${mbid(1)}`), code('ADMIN_IMPORT_LOOKUP_STALE'));
    assert.throws(choose(run, `musicbrainz:${mbid(9)}`), code('ADMIN_IMPORT_LOOKUP_STALE'));
    assert.throws(choose(run, `musicbrainz:${mbid(2)}`), code('ADMIN_IMPORT_LOOKUP_CANDIDATE_INCOMPLETE'));
    // A fetched release answered under another ID (a merged release) ranks as incomplete and is never chosen or preselected, so
    // its values never rest on evidence naming another release.
    const preselected = completed(doc, [stored(synthetic(1))]);
    const merged = { ...preselected, candidates: preselected.candidates.map(candidate => ({ ...candidate, release: synthetic(7, { title: 'Merged Target Album' }) })) };
    assert.throws(choose(merged, `musicbrainz:${mbid(1)}`), code('ADMIN_IMPORT_LOOKUP_CANDIDATE_INCOMPLETE'));
    assert.equal(completed(doc, merged.candidates).ranking!.candidates[0].status, 'incomplete');
    const target = project(2, timed);
    assert.deepEqual(applyPreselectedLookup(target, merged, now), { record: merged, changed: false });
    assert.deepEqual([draftOf(target).album.title, target.valueRevision], ['', 0]);
    // None is allowed in any finished state; a choice moves the grant to the chooser.
    for (const state of ['unavailable', 'stopped', 'superseded', 'complete'] as const) assert.equal(choose({ ...run, state }, null)().applied?.choice, 'none', state);
    const chosen = choose(run, `musicbrainz:${mbid(1)}`)();
    assert.deepEqual([chosen.applied?.choice, chosen.applied?.basis, chosen.applied?.actorId, chosen.applied?.operationId, chosen.actorId, chosen.grantSource,
        chosen.grantExpiresAt.getTime() - now.getTime()], ['chosen', 'chosen', other, mbid(703), other, 'choose', METADATA_LOOKUP_JOB_LIMITS.grantMs]);
});

test('answering a conflict: lookup writes the value as the administrator\'s own, mine keeps it, and a stale application, path or base is refused', () => {
    const setup = () => {
        const doc = project(2, timed);
        draftOf(doc).album.label = { name: 'Mine', musicBrainzId: null }; doc.draftOrigins = { 'album:label': 'administrator' };
        return { doc, record: applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now).record };
    };
    const key = `musicbrainz:${mbid(1)}`, base = { name: 'Mine', musicBrainzId: null };
    const resolve = (doc: AdminImportDocument, record: MetadataLookupRecord | null, answers: { path: string; answer: 'mine' | 'lookup'; base: unknown }[], run = 1, candidateKey: string | null = key) =>
        resolveLookupConflicts(doc, record, { run, candidateKey, answers: answers as never }, now);
    const { doc, record } = setup();
    const kept = resolve(copy(doc), record, [{ path: 'album.label', answer: 'mine', base }]);
    assert.equal(kept.applied!.conflicts[0].answer, 'mine');
    const taken = resolve(doc, record, [{ path: 'album.label', answer: 'lookup', base }]);
    assert.deepEqual([draftOf(doc).album.label, doc.draftOrigins!['album:label'], taken.applied!.conflicts[0].answer], [{ name: 'Synthetic Label', musicBrainzId: null }, 'administrator', 'lookup']);
    assert.ok(taken.applied!.values.some(value => value.path === 'album.label'));
    assert.deepEqual(lookupAnswersNeeded(taken, doc, { append: false }).conflicts, []);
    for (const [label, run, candidateKey] of [['another run', 2, key], ['another candidate', 1, `musicbrainz:${mbid(2)}`], ['none', 1, null]] as const)
        assert.throws(() => resolve(setup().doc, record, [{ path: 'album.label', answer: 'mine', base }], run, candidateKey), code('ADMIN_IMPORT_LOOKUP_STALE'), label);
    assert.throws(() => resolve(setup().doc, { ...record, applied: null }, [{ path: 'album.label', answer: 'mine', base }]), code('ADMIN_IMPORT_LOOKUP_STALE'));
    assert.throws(() => resolve(setup().doc, record, [{ path: 'album.title', answer: 'mine', base: 'Synthetic Album' }]), code('ADMIN_IMPORT_LOOKUP_STALE'));
    const fresh = setup();
    assert.throws(() => resolve(fresh.doc, fresh.record, [{ path: 'album.label', answer: 'lookup', base: { name: 'Earlier', musicBrainzId: null } }]), code('ADMIN_IMPORT_FIELD_CONFLICT'));
    assert.deepEqual(draftOf(fresh.doc).album.label, base);
    const garbage = { ...fresh.record, applied: { ...fresh.record.applied!, conflicts: [{ path: 'album.label' as const, lookup: { name: '' }, slotId: null, answer: null }] } };
    assert.throws(() => resolve(fresh.doc, garbage, [{ path: 'album.label', answer: 'lookup', base }]), code('ADMIN_IMPORT_LOOKUP_STALE'));
});

test('Artist entries and a label equal to the applied lookup values do not rest on file tags alone; differing ones still do', () => {
    const doc = project(2, timed), record = applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now).record;
    const draft = draftOf(doc), values = record.applied!.values;
    assert.deepEqual(importAutomationMarkers(draft, doc.draftOrigins).tagOnly, { artists: true, label: true });
    const marked = importAutomationMarkers(draft, doc.draftOrigins, values);
    assert.deepEqual(marked.tagOnly, { artists: false, label: false });
    // Every automatic value here rests on the candidate: all stay automatic (an administrator save wins over them) and are listed
    // as lookup values, in draft path order, so neither the editor nor the confirmation calls them file-tag values.
    assert.deepEqual(marked.lookupPaths, marked.automaticPaths);
    assert.deepEqual(marked.automaticPaths, ['album.title', 'album.artists', 'album.label', 'album.releaseDate',
        ...[0, 1].flatMap(index => ['title', 'discNumber', 'trackNumber'].map(field => `tracks.${slot(index)}.${field}`))]);
    const relabelled = structuredClone(draft); relabelled.album.label = { name: 'Synthetic Records', musicBrainzId: null };
    relabelled.album.artists = [...relabelled.album.artists, { ...entry('Company Records'), role: 'primary' }];
    const automaticPaths = importAutomationMarkers(relabelled, doc.draftOrigins).automaticPaths;
    assert.deepEqual(importAutomationMarkers(relabelled, doc.draftOrigins, values), { automaticPaths,
        lookupPaths: automaticPaths.filter(path => path !== 'album.artists' && path !== 'album.label'), possibleLabelEntryKeys: [entry('Company Records').key], tagOnly: { artists: true, label: true } });
    // Malformed lookup values never count.
    const malformed = importAutomationMarkers(draft, doc.draftOrigins, [null, { path: 7 }, { path: 'album.label' }] as never);
    assert.deepEqual([malformed.tagOnly, malformed.lookupPaths], [{ artists: true, label: true }, []]);
});

test('file-tag automation never replaces a value still resting on the applied lookup candidate, and fills the values lookup did not write', () => {
    const doc = project(2, index => tags({ title: `Tagged ${index}`, album: 'Tagged Album', albumArtists: ['Tagged Ensemble'] }));
    const { application } = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    const paths = (lookupValues: LookupApplication['values'] = []) => planImportAutomation(doc, lookupValues).values.map(value => value.path);
    assert.deepEqual(paths(), [`tracks.${slot(0)}.title`, `tracks.${slot(1)}.title`, 'album.title', 'album.artists']);
    assert.deepEqual(paths(application.values), []);
    // A value no longer equal to the applied one (changed since) and a value the candidate never wrote are planned as before.
    draftOf(doc).album.title = 'Since Changed';
    const partial = { ...application, values: application.values.filter(value => value.path !== 'album.artists') };
    assert.deepEqual(paths(partial.values), ['album.title', 'album.artists']);
    // Run on a fresh copy, the plan writes only those, leaving the chosen candidate's track titles and entries as they are.
    const result = applyAutomaticValues({ draft: draftOf(doc), draftOrigins: doc.draftOrigins! }, planImportAutomation(doc, application.values).values);
    assert.deepEqual([result.written, draftOf(doc).album.title, draftOf(doc).tracks.map(item => item.title)], [['album.title'], 'Tagged Album', ['First Song', 'Second Song']]);
});

test('answering lookup for the Artist entries keeps decisions on reused entries only, and an answer that grows the draft past its cap is invalid', () => {
    const doc = project(2, timed), kept = mbid(820), gone = mbid(821);
    draftOf(doc).album.artists = [{ key: kept, name: 'Synthetic Lead', role: 'primary', joinPhrase: null, musicBrainzId: null }, { key: gone, name: 'Mine', role: 'primary', joinPhrase: null, musicBrainzId: null }];
    doc.draftOrigins = { 'album:artists': 'administrator' };
    const decision = (entryKey: string, boundName: string) => ({ scope: 'artist', slotId: null, entryKey, boundName, action: 'create-distinct', candidateId: null, candidateRevision: null });
    doc.decisions = [decision(kept, 'Synthetic Lead'), decision(gone, 'Mine')] as AdminImportDocument['decisions'];
    const record = applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now).record;
    const conflict = record.applied!.conflicts.find(item => item.path === 'album.artists')!;
    assert.deepEqual((conflict.lookup as ImportArtistEntry[]).map(item => item.key), [kept, derivedEntryKey({ importId, lookupEntry: 'synthetic second' })]);
    const base = structuredClone(draftOf(doc).album.artists);
    const answered = resolveLookupConflicts(doc, record, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, answers: [{ path: 'album.artists', answer: 'lookup', base }] }, now);
    assert.deepEqual([draftOf(doc).album.artists.map(item => item.name), doc.draftOrigins!['album:artists'], doc.decisions.map(item => (item as { entryKey: string }).entryKey)],
        [['Synthetic Lead', 'Synthetic Second'], 'administrator', [kept]]);
    assert.deepEqual([answered.applied!.conflicts[0].answer, answered.applied!.values.find(item => item.path === 'album.artists')?.value], ['lookup', draftOf(doc).album.artists]);
    // Near the 48 KB cap, writing the longer lookup title is refused (the caller's transaction then writes nothing).
    const full = project(2, timed), slotPath = `tracks.${slot(0)}.title` as const;
    draftOf(full).tracks[0].title = 'x'; full.draftOrigins = { [`tracks:${slot(0)}:title`]: 'administrator' };
    const capped = applyPreselectedLookup(full, completed(full, [stored(synthetic(1, { media: [{ position: 1, format: 'CD', tracks: [track(1, 't'.repeat(300)), track(2, 'Second Song')] }] }))]), now).record;
    assert.deepEqual(capped.applied!.conflicts.map(item => item.path), [slotPath]);
    const draft = draftOf(full);
    draft.album.title = 'x'.repeat(48_000 - 100 - JSON.stringify({ ...draft, album: { ...draft.album, title: '' } }).length);
    const keeping = copy(full);
    assert.throws(() => resolveLookupConflicts(full, capped, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, answers: [{ path: slotPath, answer: 'lookup', base: 'x' }] }, now),
        code('ADMIN_IMPORT_INVALID_INPUT'));
    // Keeping the current value never grows the draft.
    assert.equal(resolveLookupConflicts(keeping, capped, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, answers: [{ path: slotPath, answer: 'mine', base: 'x' }] }, now)
        .applied!.conflicts[0].answer, 'mine');
});

test('a conflict stored twice for one path is needed once', () => {
    const doc = project(2, timed);
    draftOf(doc).album.label = { name: 'Mine', musicBrainzId: null }; doc.draftOrigins = { 'album:label': 'administrator' };
    const record = applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now).record;
    const doubled = { ...record, applied: { ...record.applied!, conflicts: [...record.applied!.conflicts, ...record.applied!.conflicts] } };
    assert.deepEqual(lookupAnswersNeeded(doubled, doc, { append: false }), { tie: false, conflicts: ['album.label'] });
});
